-- Task 15: controlled cancellation and refunds.
alter table public.orders add column if not exists cancellation_reason text; alter table public.orders add column if not exists cancelled_at timestamptz; alter table public.orders add column if not exists refund_reason text; alter table public.orders add column if not exists refunded_at timestamptz;
create or replace function public.cancel_order_controlled(p_order_id uuid,p_reason text,p_source_device text default 'POS') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_user uuid:=auth.uid();v_order public.orders%rowtype;v_reason text:=btrim(coalesce(p_reason,''));v_paid numeric:=0;begin if v_user is null or not public.has_permission(v_user,'order.cancel') then raise exception 'Order cancellation not permitted';end if;if v_reason='' then raise exception 'Cancellation reason is required';end if;select * into v_order from public.orders where id=p_order_id for update;if not found then raise exception 'Order not found';end if;if v_order.status in ('cancelled','refunded') or v_order.operational_status in ('cancelled','refunded') then raise exception 'Order is already cancelled/refunded';end if;select coalesce(sum(amount),0) into v_paid from public.order_payments where order_id=p_order_id and status='paid';if v_paid>0 or v_order.payment_status in ('paid','partially_paid') then raise exception 'Paid or partially paid orders must be refunded, not cancelled';end if;update public.orders set status='cancelled',operational_status='cancelled',cancellation_reason=v_reason,cancelled_at=now(),updated_at=now() where id=p_order_id;update public.restaurant_tables set status='available',current_order_id=null where current_order_id=p_order_id;insert into public.order_activity_log(order_id,event_type,actor_user_id,actor_role,source_device,entity_type,entity_id,before_data,after_data,details) values(p_order_id,'ORDER_CANCELLED',v_user,public.get_user_role(v_user)::text,p_source_device,'order',p_order_id,jsonb_build_object('status',v_order.status,'operational_status',v_order.operational_status),jsonb_build_object('status','cancelled','operational_status','cancelled'),jsonb_build_object('reason',v_reason));return jsonb_build_object('order_id',p_order_id,'status','cancelled','operational_status','cancelled','reason',v_reason);end $$;
revoke all on function public.cancel_order_controlled(uuid,text,text) from public,anon;grant execute on function public.cancel_order_controlled(uuid,text,text) to authenticated;
create or replace function public.refund_order_controlled(p_order_id uuid,p_reason text,p_source_device text default 'POS') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_user uuid:=auth.uid();v_order public.orders%rowtype;v_reason text:=btrim(coalesce(p_reason,''));v_paid numeric:=0;v_refunded numeric:=0;v_amount numeric:=0;begin if v_user is null or not public.has_permission(v_user,'order.refund') then raise exception 'Order refund not permitted';end if;if v_reason='' then raise exception 'Refund reason is required';end if;select * into v_order from public.orders where id=p_order_id for update;if not found then raise exception 'Order not found';end if;if v_order.status='refunded' or v_order.payment_status='refunded' then raise exception 'Order is already refunded';end if;if v_order.status='cancelled' and v_order.payment_status='unpaid' then raise exception 'Unpaid cancelled order has nothing to refund';end if;select coalesce(sum(case when status='paid' then amount else 0 end),0),coalesce(sum(case when status='refunded' then amount else 0 end),0) into v_paid,v_refunded from public.order_payments where order_id=p_order_id;v_amount:=greatest(v_paid-v_refunded,0);if v_amount<=0 then raise exception 'No paid amount is available to refund';end if;insert into public.order_payments(order_id,amount,payment_method,status,reference,collected_by) values(p_order_id,v_amount,coalesce(v_order.payment_method,'cash'),'refunded','Order refund: '||v_reason,v_user);update public.orders set status='refunded',operational_status='refunded',payment_status='refunded',refund_reason=v_reason,refunded_at=now(),updated_at=now() where id=p_order_id;update public.restaurant_tables set status='available',current_order_id=null where current_order_id=p_order_id;insert into public.order_activity_log(order_id,event_type,actor_user_id,actor_role,source_device,entity_type,entity_id,before_data,after_data,details) values(p_order_id,'ORDER_REFUNDED',v_user,public.get_user_role(v_user)::text,p_source_device,'order',p_order_id,jsonb_build_object('status',v_order.status,'payment_status',v_order.payment_status),jsonb_build_object('status','refunded','payment_status','refunded'),jsonb_build_object('reason',v_reason,'amount',v_amount));return jsonb_build_object('order_id',p_order_id,'status','refunded','payment_status','refunded','amount_refunded',v_amount,'reason',v_reason);end $$;
revoke all on function public.refund_order_controlled(uuid,text,text) from public,anon;grant execute on function public.refund_order_controlled(uuid,text,text) to authenticated;